"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/hero-sections/variants/01-analytics-flow";
import View1 from "./components/hero-sections/variants/02-ai-teammates";
import View2 from "./components/hero-sections/variants/03-voice-mobile";
import View3 from "./components/hero-sections/variants/04-decision-spectrum";
import View4 from "./components/hero-sections/variants/05-defi-routing";
import View5 from "./components/hero-sections/variants/06-ai-marketplace";
import View6 from "./components/hero-sections/variants/07-signal-aurora";
import View7 from "./components/hero-sections/variants/12-split-demo";
const views={"analytics-flow":View0,"ai-teammates":View1,"voice-mobile":View2,"decision-spectrum":View3,"defi-routing":View4,"ai-marketplace":View5,"signal-aurora":View6,"split-demo":View7};
export interface ArtemisHeroSectionsProps {className?:string;variant?:"analytics-flow"|"ai-teammates"|"voice-mobile"|"decision-spectrum"|"defi-routing"|"ai-marketplace"|"signal-aurora"|"split-demo";}
export function ArtemisHeroSections({className,variant="analytics-flow"}:ArtemisHeroSectionsProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View/></ArtemisScope>;}
